#POC
function !c {
[CmdletBinding()]
param (	
[Parameter (Mandatory = $False, Position=0, ValueFromPipeline = $True)]
[string]$c
)

    process {
        switch ($c) {
            1  { one   }
            2  { two   }
            3  { three }
            4  { four  }
	   default { echo "Proof of concept" }
        }
    }
}

function one   {echo "command 1"}
function two   {echo "command 2"}
function three {echo "command 3"}
function four  {echo "command 4"}
